// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(burner != address(0));
        vm.assume(mintAmount > 0 && mintAmount <= 1e30);
        vm.assume(burnAmount <= mintAmount);

        // Set burner as owner
        vm.prank(burner);
        c = new C(0, "", ""); // re-deploy with burner as owner

        // Mint tokens to burner
        vm.prank(burner);
        c.mintToken(burner, mintAmount);

        // Burn some tokens
        vm.prank(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        if (success) {
            uint256 totalSupplyAfter = c.totalSupply();
            uint256 sumBalances = c.balanceOf(burner);
            assertTrue(totalSupplyAfter == sumBalances, "After burn, totalSupply must equal sum of all balances");
        } else {
            assertTrue(false, "burn should not revert");
        }
    }
}

