// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // Bound burnAmount to avoid overflow in balance subtraction
        burnAmount = bound(burnAmount, 0, 1e30);
        // Precondition: burner has enough balance (the owner, since onlyOwner)
        vm.assume(c.balanceOf(address(this)) >= burnAmount);

        // Perform a burn
        c.burn(burnAmount);

        // After burn, totalSupply should be at least the balance of the owner
        // (This rule holds for the reference because totalSupply decreases exactly by burnAmount
        // while balance decreases by burnAmount, but for the mutant totalSupply does not increase
        // during mint, so it can become less than the owner's balance after repeated burn-mint cycles.)
        assertTrue(c.totalSupply() >= c.balanceOf(address(this)));
    }
}

