// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        // First, mint some tokens to the caller so burn is possible
        vm.prank(c.address);
        c.mintToken(caller, 100);
        // Record balance before burn
        vm.prank(caller);
        uint256 balanceBefore = c.balanceOf(caller);
        // Bound value to be <= balanceBefore so that the reference doesn't revert
        vm.assume(value <= balanceBefore);
        // Perform burn
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        if (success) {
            uint256 balanceAfter = c.balanceOf(caller);
            // The invariant: balance decreases by exactly value
            assertTrue(balanceAfter == balanceBefore - value, "Burn did not decrease balance by value");
        } else {
            // If it reverts, the rule is that the caller's balance is unchanged
            uint256 balanceAfter = c.balanceOf(caller);
            assertTrue(balanceAfter == balanceBefore, "Burn reverted but balance changed");
        }
    }
}

