pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnValue, address otherAccount) public {
        vm.assume(otherAccount != address(0) && otherAccount != address(this));
        vm.assume(burnValue > 0 && burnValue <= c.balanceOf(address(this)));

        // Use prank to set caller as a different address for the burn
        address caller = address(0x1234);
        vm.deal(caller, 1 ether);

        // Fund the caller with some tokens via mintToken (onlyOwner)
        uint256 mintAmount = 1000 ether;
        c.mintToken(caller, mintAmount);

        // Also fund otherAccount
        c.mintToken(otherAccount, 500 ether);

        // Record balances before burn
        uint256 callerBalanceBefore = c.balanceOf(caller);
        uint256 otherBalanceBefore = c.balanceOf(otherAccount);

        // Perform burn as caller
        vm.prank(caller);
        c.burn(burnValue);

        // After burn: for the correct contract, sum of balances decreases exactly by burnValue; for the buggy, sum decreases by 0 (only totalSupply decreases)
        uint256 callerBalanceAfter = c.balanceOf(caller);
        uint256 otherBalanceAfter = c.balanceOf(otherAccount);

        // The sum of balances of two distinct accounts should decrease by exactly burnValue
        uint256 sumBefore = callerBalanceBefore + otherBalanceBefore;
        uint256 sumAfter = callerBalanceAfter + otherBalanceAfter;
        assertTrue(sumBefore - sumAfter == burnValue, "Sum of two balances should decrease by burn amount");
    }
}

