pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(burner != address(0));
        // Ensure burner has enough balance by minting first
        vm.startPrank(c.owner());
        c.mintToken(burner, amount);
        vm.stopPrank();
        // Record balances before burn
        address[] memory accounts = new address[](2);
        accounts[0] = c.owner();
        accounts[1] = burner;
        uint256 sumBefore;
        for (uint256 i = 0; i < accounts.length; i++) {
            sumBefore += c.balanceOf(accounts[i]);
        }
        uint256 supplyBefore = c.totalSupply();
        // Burn from burner
        vm.prank(burner);
        c.burn(amount);
        // Sum balances after burn
        uint256 sumAfter;
        for (uint256 i = 0; i < accounts.length; i++) {
            sumAfter += c.balanceOf(accounts[i]);
        }
        uint256 supplyAfter = c.totalSupply();
        assertTrue(sumAfter == sumBefore - amount && supplyAfter == supplyBefore - amount, "sum != supply");
    }
}

