pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, address other, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);

        // Setup initial balances
        vm.deal(caller, 1 ether);
        vm.deal(other, 1 ether);

        // Give some tokens to caller via mintToken (onlyOwner)
        vm.prank(c.address);
        (bool successMint, ) = address(c).call(abi.encodeWithSignature("mintToken(address,uint256)", caller, 1000));
        vm.assume(successMint);

        // Give some tokens to other
        vm.prank(c.address);
        (bool successMint2, ) = address(c).call(abi.encodeWithSignature("mintToken(address,uint256)", other, 500));
        vm.assume(successMint2);

        // Bound burn amount
        uint256 burnAmount = bound(amount, 0, 100);

        // Record balances before burn
        uint256 callerBalBefore = c.balanceOf(caller);
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 otherBalBefore = c.balanceOf(other);

        // Attempt to burn as owner (caller is owner since we need onlyOwner)
        // Actually owner is the deployer (address(this)), so we need to impersonate
        vm.prank(address(this));
        (bool successBurn, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        // If burn succeeded
        if (successBurn) {
            uint256 totalSupplyAfter = c.totalSupply();
            uint256 callerBalAfter = c.balanceOf(caller);
            uint256 otherBalAfter = c.balanceOf(other);

            // The invariant: sum of all balances (caller + owner + other) equals totalSupply
            // We can check the change: totalSupply decrease should equal balanceOf(caller) decrease
            uint256 callerBalChange = callerBalBefore - callerBalAfter;
            uint256 totalSupplyChange = totalSupplyBefore - totalSupplyAfter;

            // In correct version, totalSupplyChange == burnAmount and callerBalChange == burnAmount
            // In buggy version, totalSupplyChange == 0, so totalSupplyChange != callerBalChange
            assertTrue(
                totalSupplyChange == callerBalChange,
                "totalSupply and balanceOf should decrease by same amount"
            );
        }
    }
}

