// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 _value) public {
        // Ensure burn amount is within totalSupply (which is 0 initially, but we want a valid test)
        // Actually, with totalSupply=0, burn would always revert. We use a non-zero supply by minting first.
        // But we must not hardcode. Instead, we use an assumption that _value <= 10^18 and mint that amount to owner.
        vm.assume(_value > 0 && _value <= 1e18);

        // Mint to owner to ensure balance
        address owner = c.owner();
        c.mintToken(owner, _value);

        // Record balances after mint
        uint256 totalBefore = c.totalSupply();
        uint256 balanceOwnerBefore = c.balanceOf(owner);

        // Burn some amount (must be <= owner's balance)
        // We ensure the burn amount is at most what owner has.
        uint256 burnAmount = bound(_value, 1, balanceOwnerBefore);
        c.burn(burnAmount);

        // After burn, totalSupply should equal previous owner's balance (since mint gave all tokens to owner)
        // More generally: totalSupply + balanceOf[owner] is invariant when owner is the only token holder
        // But here, owner is the only token holder after mint. So totalSupply == balanceOf[owner] after burn.
        uint256 totalAfter = c.totalSupply();
        uint256 balanceOwnerAfter = c.balanceOf(owner);
        // The invariant: totalAfter + balanceOwnerAfter == totalBefore + balanceOwnerBefore - 2*burnAmount? No.
        // Actually, simpler: totalAfter == balanceOwnerAfter because both decreased by burnAmount.
        assertTrue(totalAfter == balanceOwnerAfter, "totalSupply should equal owner balance");
    }
}

