import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address burner, uint256 burnAmount, address target, uint256 mintAmount) public {
        vm.assume(burner != address(0));
        vm.assume(mintAmount > 0 && burnAmount > 0);
        vm.assume(c.frozenAccount(burner) == false);
        vm.assume(c.frozenAccount(target) == false);

        // Mint first so burner has balance
        vm.prank(c.owner());
        c.mintToken(burner, mintAmount);
        vm.prank(c.owner());
        c.mintToken(target, mintAmount);

        uint256 burnerBalanceBefore = c.balanceOf(burner);
        uint256 totalSupplyBefore = c.totalSupply();

        vm.assume(burnAmount <= burnerBalanceBefore);
        vm.prank(burner);
        c.burn(burnAmount);

        uint256 totalSupplyAfter = c.totalSupply();

        // The totalSupply should decrease by exactly burnAmount (not more, not less)
        assertTrue(totalSupplyBefore - totalSupplyAfter == burnAmount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 initialSupply, uint256 burnAmount) public {
        // Restrict inputs to avoid overflow and ensure the caller has sufficient balance
        vm.assume(burner != address(0));
        vm.assume(initialSupply > 0);
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= initialSupply);

        // Deploy a new contract with the given initial supply
        // Note: totalSupply = initialSupply * 10^0 = initialSupply
        c = new C(initialSupply, "", "");

        // Simulate minting to the burner so they have enough balance to burn
        // (The owner can mint arbitrary amounts; we mint exactly initialSupply to burner)
        vm.prank(c.owner());
        c.mintToken(burner, initialSupply);

        // Record state before burn
        uint256 preBurnTotalSupply = c.totalSupply();
        uint256 preBurnCallerBalance = c.balanceOf(burner);

        // Perform burn as the burner
        vm.prank(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        // Rule: After a burn, the caller's balance plus totalSupply should not exceed pre-burn value
        // (This holds in reference because both decrease, but in mutant the balance decreases by less than expected)
        uint256 postBurnTotalSupply = c.totalSupply();
        uint256 postBurnCallerBalance = c.balanceOf(burner);
        // The sum should be strictly less than or equal to pre-burn sum (due to burn)
        // Actually, totalSupply decreases by burnAmount, caller balance decreases by burnAmount, so sum decreases by 2*burnAmount
        // In mutant, totalSupply decreases correctly but balance decreases by double? No, mutant: balance -= mintedAmount, but here mintedAmount is initialSupply, so it's just a different decrease.
        // Simpler: We assert that after a successful burn, the totalSupply is less than pre-burn (since burn reduces supply)
        // Both versions satisfy this, but the mutant will have a different relation.
        // Better: The caller's balance after burn should be pre-burn balance minus burnAmount (since they burned that many)
        // Mutant: mintToken decreases balance, so the pre-burn balance might be lower, causing the difference.
        // Let's assert: after burn, caller balance == preBurnCallerBalance - burnAmount (if burn succeeded)
        if (success && preBurnCallerBalance >= burnAmount) {
            assertTrue(c.balanceOf(burner) == preBurnCallerBalance - burnAmount, "Balance should decrease by burnAmount");
        } else {
            // If burn reverted, state unchanged
            assertTrue(c.balanceOf(burner) == preBurnCallerBalance, "Balance unchanged on revert");
            assertTrue(c.totalSupply() == preBurnTotalSupply, "Supply unchanged on revert");
        }
    }
}

