import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, address other, uint256 amount) public {
        vm.assume(burner != address(0));
        vm.assume(other != address(0));
        amount = bound(amount, 0, type(uint256).max);

        // Get frozenAccount status before burn
        bool wasFrozen = c.frozenAccount(other);

        // Perform burn as burner (but owner is msg.sender in setUp, so we need to prank the owner)
        // The burn function requires onlyOwner, so we must call as owner. 
        // To test the invariant, we just need to call burn in some way that might change frozenAccount.
        // Since M sets frozenAccount to false on the target passed to freezeAccount, but burn doesn't call freezeAccount,
        // the only way burn could affect frozenAccount is indirectly through the buggy freezeAccount being called.
        // However, burn does not call freezeAccount, so frozenAccount should remain unchanged.
        // But in M, freezeAccount is broken, but burn doesn't call it, so the invariant holds for both.
        // The test will pass on both, so it's not detecting the bug. We need a different approach.

        // Actually, the bug is in freezeAccount, but we are driving through burn. The description says:
        // "after a call to burn(...) completes, the value of frozenAccount differs at some key k".
        // This means burn must somehow trigger the freezeAccount function or the bug manifests through burn.
        // But burn does not call freezeAccount. Let me reconsider.

        // The test should drive through burn and check property. But burn does not affect frozenAccount.
        // The only way burn can cause a difference is if there's a reentrancy or other side effect.
        // Since that's not the case, the property must be that after burn, frozenAccount for any address is unchanged.
        // This holds for both P and M, so the test won't detect the bug.

        // Actually, maybe the intent is: after calling burn, the frozenAccount mapping should not change for any address.
        // This is trivially true for both, so it's not a valid test.

        // Let me think again. The description says M changes freezeAccount to always set false.
        // If we call freezeAccount before burn, then burn afterwards, the difference might appear.
        // But the drive must end with a call to burn.

        // Perhaps the test should: freeze someone, then burn, and check that frozen status persists.
        // In P, after freezeAccount(target, true), frozenAccount[target] is true.
        // In M, after freezeAccount(target, true), frozenAccount[target] is false (due to bug).
        // Then burn doesn't change frozenAccount, so the difference remains.
        // But we need to drive through burn, so we can call freezeAccount then burn, and check the ending state.

        // However, we must be careful: freezeAccount is onlyOwner, so we need to call as owner.

        // Let's write a test: freeze a random address to true, then call burn, then check that the frozen status
        // is still true for that address. This will pass on P (freezeAccount works) and fail on M (freezeAccount sets false).

        c.freezeAccount(other, true);

        // Now call burn as owner
        vm.prank(address(this)); // The constructor sets owner to msg.sender
        c.burn(amount);

        bool isFrozen = c.frozenAccount(other);
        assertTrue(isFrozen == true, "frozenAccount should remain true after burn");
    }
}

